questionvariables.text:
/* ---- randomised starting configuration (student is encouraged to drag) ---- */
ri  : rand([2,3]);
dRr : rand([1,2,3]);
Rr  : ri + dRr;                 /* R > r in the start state; formula is symmetric */
gap : rand([2,3,4]);
sep : ri + Rr + gap;           /* centres this far apart: circles fully separated */
ax  : -floor(sep/2);
bx  : ax + sep;
initA  : [ax, 0];
initB  : [bx, 0];
initAh : [ax + ri, 0];
initBh : [bx + Rr, 0];
/* values of the start configuration - used for the model answer and the tests */
d0   : sep;
L0t  : float(sqrt(d0^2 - (Rr + ri)^2));     /* correct transverse length, start config */
ta   : L0t;
/* wrong values for the start config (used by qtests) */
L0diff : float(sqrt(d0^2 - (Rr - ri)^2));   /* direct formula (used R-r) */
L0lin  : float(d0 - (Rr + ri));
/* an overlapping configuration to exercise the invalid branch: r=3, R=4, d=5 (<7) */
badA  : [0,0];  badAh : [3,0];
badB  : [5,0];  badBh : [9,0];
/* rounding helper for display in general feedback */
fr(x) := ev(float(round(x*100)/100), simp);

feedbackvariables.text:
/* reconstruct r, R, d from the bound points, then round to 2 d.p. so the
   marking uses exactly the values the student reads off the diagram (radii are
   floored at 1, matching the JavaScript). */
raw_r : max(1, float(sqrt((ans1[1]-ans2[1])^2 + (ans1[2]-ans2[2])^2)));
raw_R : max(1, float(sqrt((ans3[1]-ans4[1])^2 + (ans3[2]-ans4[2])^2)));
raw_d : float(sqrt((ans1[1]-ans3[1])^2 + (ans1[2]-ans3[2])^2));
rr : float(round(raw_r*100)/100);
RR : float(round(raw_R*100)/100);
dr : float(round(raw_d*100)/100);
disct : dr^2 - (RR + rr)^2;
discd : dr^2 - (RR - rr)^2;
Lc    : if is(disct > 0) then float(sqrt(disct)) else -1;
Ldiff : if is(discd > 0) then float(sqrt(discd)) else -1;
Llin  : float(abs(dr - (RR + rr)));
